func And(predicates ...predicate.VerifiedPurchase) predicate.VerifiedPurchase {
	return predicate.VerifiedPurchase(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VerifiedPurchase) predicate.VerifiedPurchase {
	return predicate.VerifiedPurchase(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VerifiedPurchase) predicate.VerifiedPurchase {
	return predicate.VerifiedPurchase(sql.NotPredicates(p))
}
